#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "heat-3d.h"

/* -------------------------------------------------------------------------
 * Tunable blocking factors.
 *
 * These constants control the blocking of the spatial dimensions in the
 * main kernel.  They can be overridden at compile time, e.g.:
 *
 *   gcc -O3 -DNDEBUG -DI_BLOCK_SIZE=32 -DJ_BLOCK_SIZE=8 ...
 *
 * Choose them with the target cache hierarchy in mind.
 * ------------------------------------------------------------------------- */
#ifndef I_BLOCK_SIZE
# define I_BLOCK_SIZE 32
#endif

#ifndef J_BLOCK_SIZE
# define J_BLOCK_SIZE 32
#endif


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_3D(A,N,N,N,n,n,n),
		 DATA_TYPE POLYBENCH_3D(B,N,N,N,n,n,n))
{
  int i, j, k;

  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      for (k = 0; k < n; k++)
        A[i][j][k] = B[i][j][k] = (DATA_TYPE) (i + j + (n-k))* 10 / (n);
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_3D(A,N,N,N,n,n,n))

{
  int i, j, k;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      for (k = 0; k < n; k++) {
         if ((i * n * n + j * n + k) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
         fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j][k]);
      }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied:
   - Spatial blocking in the i and j dimensions (I_BLOCK_SIZE, J_BLOCK_SIZE)
     to improve cache locality of neighboring planes.
   - The innermost loop remains over k, the fastest-varying index, to keep
     memory accesses contiguous.
   - Optional OpenMP pragmas to exploit thread-level parallelism if the code
     is compiled with -fopenmp; otherwise they are ignored by the compiler,
     preserving the original sequential semantics.
   - A compiler hint (#pragma GCC ivdep) on the k-loop to enable aggressive
     vectorization while preserving the mathematical expression structure.
*/
static
void kernel_heat_3d[[gnu::flatten, gnu::noinline]](int tsteps,
		      int n,
		      DATA_TYPE POLYBENCH_3D(A,N,N,N,n,n,n),
		      DATA_TYPE POLYBENCH_3D(B,N,N,N,n,n,n))
{
  /* Parameters are kept for API compatibility; PolyBench uses the
     compile-time constants N and TSTEPS through the _PB_* macros.
     Using the same iteration space as the reference implementation
     preserves the exact semantics. */
  (void)tsteps;
  (void)n;

  const int n_      = _PB_N;
  const int tsteps_ = TSTEPS;

  /* Interior domain bounds (exclusive upper bounds in loops below). */
  const int i_start = 1;
  const int j_start = 1;
  const int k_start = 1;
  const int i_end   = n_ - 1;
  const int j_end   = n_ - 1;
  const int k_end   = n_ - 1;

  int t, i, j, k;
  int ii, jj;

#pragma scop
  for (t = 1; t <= tsteps_; t++)
  {
    /* --------------------------------------------------------------------
     * First sweep: update B from A.
     *
     * The (i,j) plane is traversed in tiles of size
     * I_BLOCK_SIZE x J_BLOCK_SIZE.  For each tile, i and j are iterated
     * in the natural order and k remains the innermost loop to keep
     * accesses B[i][j][k] / A[i][j][k] contiguous in memory.
     * The blocking factors handle non-divisible sizes via min-like
     * clipping at the domain boundaries.
     * ------------------------------------------------------------------ */
    #pragma omp parallel for collapse(2) private(i,j,k) schedule(static)
    for (ii = i_start; ii < i_end; ii += I_BLOCK_SIZE)
    {
      for (jj = j_start; jj < j_end; jj += J_BLOCK_SIZE)
      {
        int i_block_end = ii + I_BLOCK_SIZE;
        if (i_block_end > i_end)
          i_block_end = i_end;

        int j_block_end = jj + J_BLOCK_SIZE;
        if (j_block_end > j_end)
          j_block_end = j_end;

        for (i = ii; i < i_block_end; ++i)
        {
          for (j = jj; j < j_block_end; ++j)
          {
            /* No loop-carried dependence along k: each B[i][j][k] depends
               only on A at time t and fixed (i,j), so the compiler is free
               to vectorize this loop. */
            #pragma GCC ivdep
            for (k = k_start; k < k_end; ++k)
            {
              B[i][j][k] =
                  SCALAR_VAL(0.125) *
                      (A[i+1][j][k] - SCALAR_VAL(2.0) * A[i][j][k] + A[i-1][j][k])
                + SCALAR_VAL(0.125) *
                      (A[i][j+1][k] - SCALAR_VAL(2.0) * A[i][j][k] + A[i][j-1][k])
                + SCALAR_VAL(0.125) *
                      (A[i][j][k+1] - SCALAR_VAL(2.0) * A[i][j][k] + A[i][j][k-1])
                + A[i][j][k];
            }
          }
        }
      }
    }

    /* --------------------------------------------------------------------
     * Second sweep: update A from B.
     *
     * Same traversal pattern and blocking as above, with the roles of
     * A and B swapped.  A full barrier (implied at the end of the
     * previous OpenMP 'for' when compiled with -fopenmp) ensures that
     * all B values are ready before they are read here.
     * ------------------------------------------------------------------ */
    #pragma omp parallel for collapse(2) private(i,j,k) schedule(static)
    for (ii = i_start; ii < i_end; ii += I_BLOCK_SIZE)
    {
      for (jj = j_start; jj < j_end; jj += J_BLOCK_SIZE)
      {
        int i_block_end = ii + I_BLOCK_SIZE;
        if (i_block_end > i_end)
          i_block_end = i_end;

        int j_block_end = jj + J_BLOCK_SIZE;
        if (j_block_end > j_end)
          j_block_end = j_end;

        for (i = ii; i < i_block_end; ++i)
        {
          for (j = jj; j < j_block_end; ++j)
          {
            #pragma GCC ivdep
            for (k = k_start; k < k_end; ++k)
            {
              A[i][j][k] =
                  SCALAR_VAL(0.125) *
                      (B[i+1][j][k] - SCALAR_VAL(2.0) * B[i][j][k] + B[i-1][j][k])
                + SCALAR_VAL(0.125) *
                      (B[i][j+1][k] - SCALAR_VAL(2.0) * B[i][j][k] + B[i][j-1][k])
                + SCALAR_VAL(0.125) *
                      (B[i][j][k+1] - SCALAR_VAL(2.0) * B[i][j][k] + B[i][j][k-1])
                + B[i][j][k];
            }
          }
        }
      }
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_3D_ARRAY_DECL(A, DATA_TYPE, N, N, N, n, n, n);
  POLYBENCH_3D_ARRAY_DECL(B, DATA_TYPE, N, N, N, n, n, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_heat_3d (tsteps, n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
