#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "heat-3d.h"

/* Tunable blocking factor for the j-dimension (second index).
 * Can be overridden at compile time, e.g., -DHEAT3D_BLOCK_J=64.
 * The blocking is purely for cache locality and does not affect results. */
#ifndef HEAT3D_BLOCK_J
# define HEAT3D_BLOCK_J 32
#endif


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_3D(A,N,N,N,n,n,n),
		 DATA_TYPE POLYBENCH_3D(B,N,N,N,n,n,n))
{
  int i, j, k;

  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      for (k = 0; k < n; k++)
        /* Keep arithmetic and evaluation order identical to the original
         * expression to preserve floating-point semantics exactly. */
        A[i][j][k] = B[i][j][k] =
          (DATA_TYPE) (i + j + (n-k)) * 10 / (n);
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_3D(A,N,N,N,n,n,n))

{
  int i, j, k;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      for (k = 0; k < n; k++) {
         if ((i * n * n + j * n + k) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
         fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j][k]);
      }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied:
   - Use of restrict-qualified local pointers for A and B to aid
     alias analysis and vectorization.
   - Factor out the common subexpression 2.0 * center (but *not* the
     0.125 factor) to preserve floating-point evaluation order while
     reducing redundant multiplications.
   - Spatial blocking in the j-dimension (tunable HEAT3D_BLOCK_J) to
     improve cache locality for large problem sizes.
   - Time-stepping rewritten as a single unified stencil update that
     alternates source and destination (A/B) via pointer swapping.
     This performs exactly the same sequence of updates as the
     original "A->B then B->A" pattern for each time step, but with
     a single, more cache- and I-cache-friendly loop nest.
*/
static
void __attribute__((noinline))
kernel_heat_3d(int tsteps,
	       int n,
	       DATA_TYPE POLYBENCH_3D(A,N,N,N,n,n,n),
	       DATA_TYPE POLYBENCH_3D(B,N,N,N,n,n,n))
{
  int t, i, j, k;

  /* Effective interior bounds:
   * Original loops were:
   *   for (i = 1; i < _PB_N-1; i++)
   * so we keep that exact range via n_inner = _PB_N - 1.
   */
  const int n_inner = _PB_N - 1;

  /* Local restrict-qualified pointers improve alias analysis and
   * allow better vectorization than using the raw parameters. */
  DATA_TYPE (* __restrict A_)[n][n] = A;
  DATA_TYPE (* __restrict B_)[n][n] = B;

  const DATA_TYPE c0_125 = SCALAR_VAL(0.125);
  const DATA_TYPE c2     = SCALAR_VAL(2.0);

#pragma scop
  /* Each original time step performed two full sweeps:
   *   1) A -> B
   *   2) B -> A
   * Here we perform 2*tsteps "half-steps". At even half-steps
   * we do A -> B, at odd half-steps B -> A. The sequence of
   * updates in time and the final contents of A are identical. */
  const int total_steps = 2 * tsteps;

  for (t = 0; t < total_steps; ++t)
  {
    DATA_TYPE (* __restrict src)[n][n];
    DATA_TYPE (* __restrict dst)[n][n];

    /* Alternate source and destination every half-step:
     * t even:  src = A, dst = B (A -> B)
     * t odd:   src = B, dst = A (B -> A) */
    if ((t & 1) == 0) {
      src = A_;
      dst = B_;
    } else {
      src = B_;
      dst = A_;
    }

    /* Interior domain [1, n_inner-1] in each dimension. */
    const int i_start = 1;
    const int i_end   = n_inner;
    const int j_start = 1;
    const int j_end   = n_inner;
    const int k_start = 1;
    const int k_end   = n_inner;

    /* Simple blocking in j to improve spatial locality for large n.
     * k remains the innermost loop to preserve unit-stride accesses. */
    const int BJ = HEAT3D_BLOCK_J;

    for (i = i_start; i < i_end; ++i) {
      for (int jj = j_start; jj < j_end; jj += BJ) {
        int j_max = jj + BJ;
        if (j_max > j_end)
          j_max = j_end;

        for (j = jj; j < j_max; ++j) {
          /* No loop-carried dependencies in k; this hints to GCC that
           * the loop is safe to vectorize even in the presence of
           * possible aliasing elsewhere. */
#pragma GCC ivdep
          for (k = k_start; k < k_end; ++k) {
            const DATA_TYPE center  = src[i][j][k];
            const DATA_TYPE center2 = c2 * center;

            /* Compute the three directional second-difference terms.
             * The structure and evaluation order of these expressions
             * (other than reusing center2) matches the original code. */
            DATA_TYPE t1 = src[i+1][j][k] - center2 + src[i-1][j][k];
            DATA_TYPE t2 = src[i][j+1][k] - center2 + src[i][j-1][k];
            DATA_TYPE t3 = src[i][j][k+1] - center2 + src[i][j][k-1];

            /* Preserve original arithmetic structure:
             *   0.125 * t1 + 0.125 * t2 + 0.125 * t3 + center
             * rather than factoring 0.125 outside, to keep
             * floating-point semantics identical. */
            dst[i][j][k] =
                c0_125 * t1
              + c0_125 * t2
              + c0_125 * t3
              + center;
          }
        }
      }
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
