  /* Hoist constant conversions out of the loops to reduce overhead. */
  const DATA_TYPE fn     = (DATA_TYPE)n;
  const DATA_TYPE factor = SCALAR_VAL(10.0);

  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      /* Pointers to the contiguous k-lines for this (i,j). */
      DATA_TYPE *restrict A_ij = A[i][j];
      DATA_TYPE *restrict B_ij = B[i][j];

#pragma GCC ivdep
      for (k = 0; k < n; k++) {
        /* Preserve the original arithmetic structure:
           ((i + j + (n-k)) * 10) / n */
        const DATA_TYPE val =
          (((DATA_TYPE)(i + j + (n - k))) * factor) / fn;

        A_ij[k] = val;
        B_ij[k] = val;
      }
    }
