static
void kernel_heat_3d[[gnu::flatten, gnu::noinline]](int tsteps,
                      int n,
                      DATA_TYPE POLYBENCH_3D(A,N,N,N,n,n,n),
                      DATA_TYPE POLYBENCH_3D(B,N,N,N,n,n,n))
{
  int t, i, j, k;

  /* Keep using PolyBench's macro-based bounds to stay compatible with
     the framework, but cache them locally for the optimizer. */
  const int t_end   = TSTEPS;
  const int n_space = _PB_N;

  /* Parameters are kept for interface compatibility; silence
     potential unused warnings. */
  (void)tsteps;
  (void)n;

  /* Degenerate sizes: original loops would simply not execute. */
  if (n_space <= 2 || t_end <= 0)
    return;

  /* Precompute constants used in the stencil; using SCALAR_VAL keeps
