     PolyBench allocators guarantee POLYBENCH_ALIGNMENT-byte alignment,
     so this assumption is valid and helps vectorization. */
  DATA_TYPE (*restrict A_aligned)[n][n] =
    (DATA_TYPE (*restrict)[n][n])__builtin_assume_aligned(
      A, POLYBENCH_ALIGNMENT);
  DATA_TYPE (*restrict B_aligned)[n][n] =
    (DATA_TYPE (*restrict)[n][n])__builtin_assume_aligned(
      B, POLYBENCH_ALIGNMENT);

  const int i_start = 1;
  const int j_start = 1;
  const int k_start = 1;
  const int i_end   = n_space - 1; /* exclusive upper bounds */
  const int j_end   = n_space - 1;
  const int k_end   = n_space - 1;

#pragma scop
  for (t = 1; t <= t_end; t++) {

    /* ------------------------------------------------------------------
     * Time step t: update B from A.
     *
     *  - 3D spatial blocking improves cache locality.
     *  - k remains the innermost loop to stream contiguous memory.
     *  - Per-(i,j) pointers reduce address arithmetic in the k-loop.
     * ------------------------------------------------------------------ */
    for (int ii = i_start; ii < i_end; ii += TILE_I) {
      const int i_max = (ii + TILE_I < i_end) ? ii + TILE_I : i_end;

      for (int jj = j_start; jj < j_end; jj += TILE_J) {
        const int j_max = (jj + TILE_J < j_end) ? jj + TILE_J : j_end;

        for (int kk = k_start; kk < k_end; kk += TILE_K) {
          const int k_max = (kk + TILE_K < k_end) ? kk + TILE_K : k_end;

          for (i = ii; i < i_max; i++) {
            /* Neighboring x-planes for this i. */
            DATA_TYPE (*restrict A_ip1)[n] = A_aligned[i+1];
            DATA_TYPE (*restrict A_i  )[n] = A_aligned[i];
            DATA_TYPE (*restrict A_im1)[n] = A_aligned[i-1];
            DATA_TYPE (*restrict B_i  )[n] = B_aligned[i];

            for (j = jj; j < j_max; j++) {
              /* For fixed (i,j) we have a contiguous line in k.
                 Cache all planes participating in the stencil. */
              DATA_TYPE *restrict A_ip1j = A_ip1[j];
              DATA_TYPE *restrict A_ij   = A_i[j];
              DATA_TYPE *restrict A_im1j = A_im1[j];
              DATA_TYPE *restrict A_ijp1 = A_i[j+1];
              DATA_TYPE *restrict A_ijm1 = A_i[j-1];
              DATA_TYPE *restrict B_ij   = B_i[j];

#pragma GCC ivdep
              for (k = kk; k < k_max; k++) {
                const DATA_TYPE center = A_ij[k];

                B_ij[k] =   c0 * (A_ip1j[k] - c2 * center + A_im1j[k])
                          + c0 * (A_ijp1[k] - c2 * center + A_ijm1[k])
                          + c0 * (A_ij[k+1] - c2 * center + A_ij[k-1])
                          + center;
              }
            }
          }
        }
      }
    }

    /* ------------------------------------------------------------------
     * Time step t: update A from B.
     *
     * Layout and blocking are identical to the A->B sweep, just with
     * A and B swapped.  This symmetry helps the compiler generate
     * similarly optimized code for both directions.
     * ------------------------------------------------------------------ */
    for (int ii = i_start; ii < i_end; ii += TILE_I) {
      const int i_max = (ii + TILE_I < i_end) ? ii + TILE_I : i_end;

      for (int jj = j_start; jj < j_end; jj += TILE_J) {
        const int j_max = (jj + TILE_J < j_end) ? jj + TILE_J : j_end;

        for (int kk = k_start; kk < k_end; kk += TILE_K) {
          const int k_max = (kk + TILE_K < k_end) ? kk + TILE_K : k_end;

          for (i = ii; i < i_max; i++) {
            DATA_TYPE (*restrict B_ip1)[n] = B_aligned[i+1];
            DATA_TYPE (*restrict B_i  )[n] = B_aligned[i];
            DATA_TYPE (*restrict B_im1)[n] = B_aligned[i-1];
            DATA_TYPE (*restrict A_i  )[n] = A_aligned[i];

            for (j = jj; j < j_max; j++) {
              DATA_TYPE *restrict B_ip1j = B_ip1[j];
              DATA_TYPE *restrict B_ij   = B_i[j];
              DATA_TYPE *restrict B_im1j = B_im1[j];
              DATA_TYPE *restrict B_ijp1 = B_i[j+1];
              DATA_TYPE *restrict B_ijm1 = B_i[j-1];
              DATA_TYPE *restrict A_ij   = A_i[j];

#pragma GCC ivdep
              for (k = kk; k < k_max; k++) {
                const DATA_TYPE center = B_ij[k];

                A_ij[k] =   c0 * (B_ip1j[k] - c2 * center + B_im1j[k])
                          + c0 * (B_ijp1[k] - c2 * center + B_ijm1[k])
                          + c0 * (B_ij[k+1] - c2 * center + B_ij[k-1])
                          + center;
              }
            }
          }
        }
      }
    }

  }
#pragma endscop

}


