 *
 * Optimizations applied:
 *  - Use restrict-qualified local aliases for A and B to give the
 *    compiler stronger aliasing guarantees and enable better
 *    vectorization.
 *  - Apply 2D spatial blocking in (i,j) to improve cache locality
 *    for large grids while keeping k as the innermost (contiguous)
 *    dimension for efficient vector loads/stores.
 *  - Hoist frequently used scalar coefficients out of loops.
 *  - Avoid redundant loads of the center value A[i][j][k] / B[i][j][k]
 *    by storing it in a local variable inside the innermost loop.
 *  - Preserve the original arithmetic structure (parenthesization)
 *    of the stencil to maintain numerical behavior.
 */
static
void kernel_heat_3d[[gnu::flatten, gnu::noinline]](int tsteps,
		      int n,
		      DATA_TYPE POLYBENCH_3D(A,N,N,N,n,n,n),
		      DATA_TYPE POLYBENCH_3D(B,N,N,N,n,n,n))
{
  int t;

  /* Create restrict-qualified aliases that make the true data layout
     explicit: A_ and B_ are pointers to 2D planes of size [n][n].
     This helps the compiler perform alias analysis and vectorization. */
  DATA_TYPE (* restrict A_)[n][n] = A;
  DATA_TYPE (* restrict B_)[n][n] = B;

  /* Effective problem size used inside the PolyBench kernel.
     It can be <= n if PolyBench is configured to use smaller
     loop bounds for validation or cache flushing. */
  const int N = _PB_N;

  /* Interior region: indices where the 7-point stencil is applied.
     Boundaries [0] and [N-1] are left untouched. */
  const int i_start = 1;
  const int j_start = 1;
  const int k_start = 1;
  const int i_end   = N - 1; /* first index past interior in i */
  const int j_end   = N - 1; /* first index past interior in j */
  const int k_end   = N - 1; /* first index past interior in k */

  /* Tunable blocking factors for i and j.
     Exposed as constants so they can easily be tuned. */
  const int BLOCK_I = HEAT3D_BLOCK_I;
  const int BLOCK_J = HEAT3D_BLOCK_J;

  /* Frequently used scalar coefficients. */
  const DATA_TYPE c0_125 = SCALAR_VAL(0.125);
  const DATA_TYPE c2     = SCALAR_VAL(2.0);

  /* tsteps is kept for interface compatibility; in the PolyBench
     harness it is always equal to TSTEPS. */
  (void)tsteps;

#pragma scop
  for (t = 1; t <= TSTEPS; t++) {

    /* First sweep: update B from A. */
    for (int ii = i_start; ii < i_end; ii += BLOCK_I) {
      const int i_max = (ii + BLOCK_I < i_end) ? (ii + BLOCK_I) : i_end;

      for (int jj = j_start; jj < j_end; jj += BLOCK_J) {
        const int j_max = (jj + BLOCK_J < j_end) ? (jj + BLOCK_J) : j_end;

        for (int i = ii; i < i_max; ++i) {
          /* Plane pointers along the i dimension. */
          DATA_TYPE (* restrict A_ip1)[n] = A_[i + 1];
          DATA_TYPE (* restrict A_i  )[n] = A_[i];
          DATA_TYPE (* restrict A_im1)[n] = A_[i - 1];
          DATA_TYPE (* restrict B_i  )[n] = B_[i];

          for (int j = jj; j < j_max; ++j) {
            /* Row pointers along the j dimension. */
            DATA_TYPE * restrict Bij  = B_i[j];
            DATA_TYPE * restrict Aij  = A_i[j];
            DATA_TYPE * restrict Aipj = A_ip1[j];
            DATA_TYPE * restrict Aimj = A_im1[j];
            DATA_TYPE * restrict Aijp = A_i[j + 1];
            DATA_TYPE * restrict Aijm = A_i[j - 1];

            /* Innermost loop traverses the contiguous k dimension.
               The computation for each k is independent which allows
               efficient auto-vectorization. */
            for (int k = k_start; k < k_end; ++k) {
              const DATA_TYPE center = Aij[k];

              /* Keep arithmetic grouping identical to the original
                 formulation while avoiding redundant loads. */
              const DATA_TYPE term_i =
                c0_125 * (Aipj[k] - c2 * center + Aimj[k]);
              const DATA_TYPE term_j =
                c0_125 * (Aijp[k] - c2 * center + Aijm[k]);
              const DATA_TYPE term_k =
                c0_125 * (Aij[k + 1] - c2 * center + Aij[k - 1]);

              Bij[k] = term_i + term_j + term_k + center;
            }
          }
        }
      }
    }

    /* Second sweep: update A from B (same pattern, A and B swapped). */
    for (int ii = i_start; ii < i_end; ii += BLOCK_I) {
      const int i_max = (ii + BLOCK_I < i_end) ? (ii + BLOCK_I) : i_end;

      for (int jj = j_start; jj < j_end; jj += BLOCK_J) {
        const int j_max = (jj + BLOCK_J < j_end) ? (jj + BLOCK_J) : j_end;

        for (int i = ii; i < i_max; ++i) {
          DATA_TYPE (* restrict B_ip1)[n] = B_[i + 1];
          DATA_TYPE (* restrict B_i  )[n] = B_[i];
          DATA_TYPE (* restrict B_im1)[n] = B_[i - 1];
          DATA_TYPE (* restrict A_i  )[n] = A_[i];

