            DATA_TYPE * restrict Aij  = A_i[j];
            DATA_TYPE * restrict Bij  = B_i[j];
            DATA_TYPE * restrict Bipj = B_ip1[j];
            DATA_TYPE * restrict Bimj = B_im1[j];
            DATA_TYPE * restrict Bijp = B_i[j + 1];
            DATA_TYPE * restrict Bijm = B_i[j - 1];

