              const DATA_TYPE term_k =
                c0_125 * (Bij[k + 1] - c2 * center + Bij[k - 1]);

              Aij[k] = term_i + term_j + term_k + center;
            }
          }
        }
      }
    }
  }
#pragma endscop

}


